select
id, perm_code, perm_name, perm_desc, menu_path, status, create_time, update_time
from permission


        and id = #{id}


        and perm_code = #{permCode}


        and perm_name = #{permName}


        and perm_desc = #{permDesc}


        and menu_path = #{menuPath}


        and status = #{status}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from permission


        and id = #{id}


        and perm_code = #{permCode}


        and perm_name = #{permName}


        and perm_desc = #{permDesc}


        and menu_path = #{menuPath}


        and status = #{status}


        and create_time = #{createTime}


        and update_time = #{updateTime}
